#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        max_threads = omp_get_num_threads();
    }

    std::vector<long long> block_sum(max_threads, 0);
    std::vector<long long> block_offset(max_threads, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T   = omp_get_num_threads();

        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(T);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(T);

        long long local_sum = 0;
        for (std::size_t i = start; i < end; ++i) {
            local_sum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(local_sum); // local (block) prefix sum
        }
        block_sum[tid] = local_sum;

        #pragma omp barrier

        #pragma omp single
        {
            long long running = 0;
            for (int t = 0; t < T; ++t) {
                block_offset[t] = running;
                running += block_sum[t];
            }
        }

        #pragma omp barrier

        const long long off = block_offset[tid];
        for (std::size_t i = start; i < end; ++i) {
            output[i] = static_cast<int>(output[i] + off);
        }
    }
}
