#include <vector>
#include <cstddef>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        int T   = omp_get_num_threads();

        std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(T);
        std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(T);

        // 1) Per-thread local prefix sum on its block
        long long local_sum = 0;
        for (std::size_t i = start; i < end; ++i) {
            local_sum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(local_sum);
        }

        // 2) Publish each block sum in output[end-1] (if block non-empty)
        //    and compute block offsets in a single thread.
        #pragma omp barrier
        #pragma omp single
        {
            long long carry = 0;
            for (int t = 0; t < T; ++t) {
                std::size_t s = (n * static_cast<std::size_t>(t)) / static_cast<std::size_t>(T);
                std::size_t e = (n * static_cast<std::size_t>(t + 1)) / static_cast<std::size_t>(T);

                long long bsum = 0;
                if (e > s) {
                    bsum = static_cast<long long>(output[e - 1]); // local block total
                }

                // Store offset for block t at its first element (if non-empty)
                if (e > s) {
                    output[s] = static_cast<int>(carry);
                }

                carry += bsum;
            }
        }
        #pragma omp barrier

        // 3) Read this block's offset and add to all local elements
        long long offset = 0;
        if (end > start) {
            offset = static_cast<long long>(output[start]);
            for (std::size_t i = start; i < end; ++i) {
                output[i] = static_cast<int>(static_cast<long long>(output[i]) + offset);
            }
        }
    }
}
